def producesubstrings(s, x):
	subs = []
	for i in range(0, len(s) - x + 1):
		subs.append(s[i:x + i])
	return subs
t = int(input())
while t:
	answer = []
	t = t - 1
	n = int(input())
	s = input()
	list = s.split()
	min = len(list[0])
	smalleststring = list[0]
	smallstrings = []
	for s in list:
		if len(s) < min:
			min = len(s)
			smalleststring = s
	for s in list:
		if len(s) == len(smalleststring):
			smallstrings.append(s)
	for ss in smallstrings:
		for i in range(len(ss), 0, -1):
			flag = 0
			subs = producesubstrings(ss, i)
			for s in subs:
				flag = 0
				for x in list:
					if not s in x:
						flag = 1
						break
				if flag == 0:
					answer.append(s)
			if flag == 0:
				break
	max = len(answer[0])
	for a in answer:
		if len(a) > max:
			max = len(a)
	answer1 = []
	for a in answer:
		if len(a) == max:
			answer1.append(a)
	answer1.sort()
	print(answer1[0])
